def eh_primo(n):
    """Verifica se um número é primo."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

# Exemplo de uso
print(eh_primo(17))  # Output: True
print(eh_primo(20))  # Output: False

def fatorial(n):
    """
    Calcula o fatorial de um número usando recursão.
    """
    if n < 0:
        raise ValueError("Número deve ser não-negativo")
    if n == 0 or n == 1:
        return 1
    return n * fatorial(n - 1)

# Versão iterativa
def fatorial_iterativo(n):
    """Calcula fatorial de forma iterativa."""
    if n < 0:
        raise ValueError("Número deve ser não-negativo")

    resultado = 1
    for i in range(2, n + 1):
        resultado *= i
    return resultado

# Exemplo de uso
print(fatorial(5))  # Output: 120
print(fatorial_iterativo(5))  # Output: 120

class Pilha:
    """Implementação de uma pilha (LIFO - Last In, First Out)."""

    def __init__(self):
        self._itens = []

    def push(self, item):
        """Adiciona item ao topo da pilha."""
        self._itens.append(item)

    def pop(self):
        """Remove e retorna o item do topo."""
        if self.esta_vazia():
            raise IndexError("Pilha vazia")
        return self._itens.pop()

    def peek(self):
        """Retorna o item do topo sem remover."""
        if self.esta_vazia():
            raise IndexError("Pilha vazia")
        return self._itens[-1]

    def esta_vazia(self):
        """Verifica se a pilha está vazia."""
        return len(self._itens) == 0

    def tamanho(self):
        """Retorna o número de elementos."""
        return len(self._itens)

# Exemplo de uso
pilha = Pilha()
pilha.push(10)
pilha.push(20)
pilha.push(30)
print(pilha.pop())  # Output: 30
print(pilha.peek())  # Output: 20
